sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float radius;
uniform float amount;
uniform float edgeSoft;
uniform float edgeDark;
uniform float gloss;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float rad = radius * length(size) * 0.5;
    float2 q = (coord - ctr) / rad;
    float r = length(q);
    float rc = min(r, 0.999);
    float z = sqrt(1.0 - rc * rc);
    float rs = atan(rc, z) / 1.5707963;
    float nr = r + (rs - r) * amount;
    float2 s = ctr + q / max(r, 0.0001) * nr * rad;
    float4 lens = tex(s);
    lens = float4(lens.rgb * (1.0 - edgeDark * r * r), lens.a);
    float spec = pow(saturate(z), 12.0) * gloss * smoothstep(0.0, 0.5, 1.0 - length(q - float2(-0.3, -0.35)));
    lens = float4(lens.rgb + spec * lens.a, lens.a);
    float inside = 1.0 - smoothstep(1.0 - edgeSoft - 0.001, 1.0, r);
    return fin(c, mix(c, lens, inside), opacity);
}
